/* @autogenerated */
import { OfflineFile, OfflineOp, OfflineRead, OfflineShadow } from './offline.model';

const DB_NAME = 'offline-queue';
const DB_VERSION = 1;

/** Almacenes de la base: operaciones, estado local de las entidades, adjuntos y lecturas. */
export type OfflineStore = 'ops' | 'shadows' | 'files' | 'reads';

interface Records {
  ops: OfflineOp;
  shadows: OfflineShadow;
  files: OfflineFile;
  reads: OfflineRead;
}

/** Acceso mínimo a IndexedDB con promesas. Todos los almacenes tienen el índice `scope`. */
export class OfflineDb {
  private db?: Promise<IDBDatabase>;

  constructor(private readonly name: string = DB_NAME) {}

  /** IndexedDB disponible (no lo está en algunos modos privados ni fuera del navegador). */
  static available(): boolean {
    return typeof indexedDB !== 'undefined';
  }

  all<S extends OfflineStore>(store: S, scope: string): Promise<Records[S][]> {
    return this.run(store, 'readonly', (os) => os.index('scope').getAll(scope));
  }

  get<S extends OfflineStore>(store: S, key: IDBValidKey): Promise<Records[S] | undefined> {
    return this.run(store, 'readonly', (os) => os.get(key));
  }

  /** Guarda el registro; devuelve su clave (el `seq` asignado en `ops`). */
  put<S extends OfflineStore>(store: S, value: Records[S]): Promise<IDBValidKey> {
    return this.run(store, 'readwrite', (os) => os.put(value));
  }

  delete(store: OfflineStore, key: IDBValidKey): Promise<void> {
    return this.run(store, 'readwrite', (os) => os.delete(key)).then(() => undefined);
  }

  /** Borra las lecturas guardadas antes de `before`. */
  prune(before: number): Promise<void> {
    return this.connect().then(
      (db) =>
        new Promise<void>((resolve, reject) => {
          const tx = db.transaction('reads', 'readwrite');
          const request = tx.objectStore('reads').index('at').openCursor(IDBKeyRange.upperBound(before));
          request.onsuccess = () => {
            const cursor = request.result;
            if (cursor) {
              cursor.delete();
              cursor.continue();
            }
          };
          tx.oncomplete = () => resolve();
          tx.onerror = () => reject(tx.error);
        }),
    );
  }

  private run<R>(
    store: OfflineStore,
    mode: IDBTransactionMode,
    action: (os: IDBObjectStore) => IDBRequest,
  ): Promise<R> {
    return this.connect().then(
      (db) =>
        new Promise<R>((resolve, reject) => {
          const tx = db.transaction(store, mode);
          const request = action(tx.objectStore(store));
          tx.oncomplete = () => resolve(request.result as R);
          tx.onerror = () => reject(tx.error);
          tx.onabort = () => reject(tx.error);
        }),
    );
  }

  private connect(): Promise<IDBDatabase> {
    if (!this.db) {
      this.db = new Promise<IDBDatabase>((resolve, reject) => {
        const request = indexedDB.open(this.name, DB_VERSION);
        request.onupgradeneeded = () => {
          const db = request.result;
          db.createObjectStore('ops', { keyPath: 'seq', autoIncrement: true }).createIndex('scope', 'scope');
          db.createObjectStore('shadows', { keyPath: 'id' }).createIndex('scope', 'scope');
          db.createObjectStore('files', { keyPath: 'id' }).createIndex('scope', 'scope');
          const reads = db.createObjectStore('reads', { keyPath: 'id' });
          reads.createIndex('scope', 'scope');
          reads.createIndex('at', 'at');
        };
        request.onsuccess = () => resolve(request.result);
        request.onerror = () => reject(request.error);
      });
    }
    return this.db;
  }
}
